import { comment, commonEvent, showText } from "rpgmaker-event-dsl";

export const commonEventEvidenceCommonEvent001 = commonEvent({
  id: 1,
  name: "Evidence Common Event",
  trigger: "none",
  commands: [
    showText({ lines: ["Synthetic CR\rkept",""], face: { image: null, index: 0 }, background: "dim", position: "top" }),
    comment({ lines: ["Self-authored fixture",""] }),
  ],
});
import { mapEvent, page } from "rpgmaker-event-dsl";

export const mapEventCompleteBlank001 = mapEvent({
  mapId: 1,
  id: 1,
  name: "Complete blank",
  note: "  <tag: x>\r\n\n<tag:y>\rtrailing\n",
  x: 0,
  y: 0,
  pages: [
    page({
      commands: [

      ],
    })
  ],
});
import { switchDefinition, variableDefinition } from "rpgmaker-event-dsl";

export const switchNamed001 = switchDefinition({
  id: 1,
  name: "Named",
});

export const switchLast003 = switchDefinition({
  id: 3,
  name: "Last",
});
export {};
import { commonEvent, setMovementRoute } from "rpgmaker-event-dsl";
const instruction = {"kind":"switchOff","switch":{"kind":"switch","id":1,"name":"Named"}} as never;
export const untyped = commonEvent({ id: 2, name: "Untyped", trigger: "none", commands: [setMovementRoute({ target: { kind: "runtimeSelector", scope: "character", target: "player" }, route: { commands: [instruction] } })] });
